 146	    public final void joinOrRun() {
 147	        // Emphasize common UNFORKED case.
 148	        if (actuallyForked == UNFORKED) {
 149	            this.compute();
 150	        } else {
 151	            // java.util.concurrent has no helpJoin(); its join() already
 152	            // helps by running queued subtasks when called from a worker
 153	            // thread, so FORTRESS_HELP_JOIN (useHelpJoin) is now a no-op.
 154	            //
 155	            // That helping breaks an invariant jsr166y's blocking join
 156	            // preserved: generated compute() bodies point the worker's
 157	            // current-task field at themselves (BaseTask.setTask) and never
 158	            // restore it, and the transaction statics below resolve the
 159	            // current transaction through that field.  A task run on this
 160	            // thread while join() helps leaves the field pointing at an
 161	            // unrelated task, corrupting transaction state in the joiner's
 162	            // continuation.  Save and restore the field across join(),
 163	            // mirroring Evaluator's setCurrentTask(currentTask) after
 164	            // TupleTask.invokeAll on the interpreter side.
 165	            Thread thread = Thread.currentThread();
 166	            if (thread instanceof FortressTaskRunner) {
 167	                FortressTaskRunner ftr = (FortressTaskRunner) thread;
 168	                BaseTask saved = ftr.task();
 169	                try {
 170	                    this.join();
 171	                } finally {
 172	                    ftr.setTask(saved);
 173	                }
 174	            } else {
 175	                this.join();
 176	            }
 177	        }
 178	    }
